class ChapsService_GetSlotList_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static ChapsService::GetSlotListCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
    std::unique_ptr<ChapsService_GetSlotList_ProxyToResponder> proxy(
        new ChapsService_GetSlotList_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&ChapsService_GetSlotList_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~ChapsService_GetSlotList_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  ChapsService_GetSlotList_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "ChapsService::GetSlotListCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      const std::vector<uint64_t>& in_slot_list, uint32_t in_result);
};

bool ChapsService_GetSlotList_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::ChapsService_GetSlotList_ResponseParams_Data* params =
      reinterpret_cast<
          internal::ChapsService_GetSlotList_ResponseParams_Data*>(
              message->mutable_payload());
  
  bool success = true;
  std::vector<uint64_t> p_slot_list{};
  uint32_t p_result{};
  ChapsService_GetSlotList_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadSlotList(&p_slot_list))
    success = false;
  if (success)
    p_result = input_data_view.result();
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        ChapsService::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run(
std::move(p_slot_list), 
std::move(p_result));
  return true;
}

